for label,code,kind,seed,prompt in specs:
    work=root/label/'작업기록'
    work.mkdir(parents=True,exist_ok=True)
    flow=json.loads(json.dumps(base))
    flow['1']['inputs']['image']=f'{label}_{kind}_시작장면.png'
    flow['5']['inputs']['prompt']=prompt
    flow['6']['inputs']['noise_seed']=seed
    flow['13']['inputs']['filename_prefix']=f'ProjectRunUltimate/{code}_{kind}_512_v01'
    (work/f'{kind}_생성프롬프트.txt').write_text(prompt,encoding='utf-8')
    (work/f'{kind}_영상워크플로.json').write_text(json.dumps(flow,ensure_ascii=False,indent=2),encoding='utf-8')
    print(work/f'{kind}_영상워크플로.json')
